package com.xiahu.reader;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.*;
/** Hide system status icons during reading, retaining clock/battery in the same safe strip. */
final class ReaderSystemUi {
 private final Activity host;private final FrameLayout root;private final LinearLayout strip;private final TextView clock,battery;private final Handler handler=new Handler(Looper.getMainLooper());private boolean hidden,reading,registered;private String theme="paper";
 private final Runnable tick=new Runnable(){public void run(){update();handler.postDelayed(this,60000-System.currentTimeMillis()%60000+100);}};
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){update();}};
 ReaderSystemUi(Activity a,FrameLayout parent){host=a;root=parent;float density=a.getResources().getDisplayMetrics().density;strip=new LinearLayout(a);strip.setGravity(Gravity.CENTER_VERTICAL);strip.setPadding((int)(16*density),0,(int)(16*density),0);clock=new TextView(a);battery=new TextView(a);clock.setTextSize(12);battery.setTextSize(12);clock.setContentDescription("阅读时钟");battery.setContentDescription("阅读电量");strip.addView(clock,new LinearLayout.LayoutParams(0,-2,1));strip.addView(battery,new LinearLayout.LayoutParams(-2,-2));strip.setVisibility(View.GONE);root.setClipToPadding(false);root.addView(strip,new FrameLayout.LayoutParams(-1,1,Gravity.TOP));if(Build.VERSION.SDK_INT>=30)host.getWindow().setDecorFitsSystemWindows(false);else host.getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN);
 root.setOnApplyWindowInsetsListener((v,insets)->{int l,t,r,b,status;boolean visible=true;if(Build.VERSION.SDK_INT>=30){Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()),stable=insets.getInsetsIgnoringVisibility(WindowInsets.Type.statusBars()|WindowInsets.Type.displayCutout());l=bars.left;r=bars.right;b=bars.bottom;t=bars.top;status=stable.top;visible=insets.isVisible(WindowInsets.Type.statusBars());}else{l=insets.getSystemWindowInsetLeft();r=insets.getSystemWindowInsetRight();b=insets.getSystemWindowInsetBottom();t=insets.getSystemWindowInsetTop();int resource=host.getResources().getIdentifier("status_bar_height","dimen","android");status=resource>0?host.getResources().getDimensionPixelSize(resource):t;if(Build.VERSION.SDK_INT>=28&&insets.getDisplayCutout()!=null){DisplayCutout cut=insets.getDisplayCutout();l=Math.max(l,cut.getSafeInsetLeft());r=Math.max(r,cut.getSafeInsetRight());status=Math.max(status,cut.getSafeInsetTop());}visible=!hidden;}
 int top=Math.max(t,status);v.setPadding(l,top,r,b);FrameLayout.LayoutParams params=(FrameLayout.LayoutParams)strip.getLayoutParams();params.height=top;params.topMargin=-top;strip.setLayoutParams(params);strip.setVisibility(hidden&&!visible?View.VISIBLE:View.GONE);return insets.consumeSystemWindowInsets();});
 IntentFilter filter=new IntentFilter();filter.addAction(Intent.ACTION_BATTERY_CHANGED);filter.addAction(Intent.ACTION_TIME_CHANGED);filter.addAction(Intent.ACTION_TIMEZONE_CHANGED);a.registerReceiver(receiver,filter);registered=true;handler.post(tick);
 }
 void configure(boolean active,boolean hide,String value){reading=active;hidden=active&&hide;theme=value;int bg=active?("night".equals(theme)?Color.rgb(29,39,34):"warm".equals(theme)?Color.rgb(234,217,184):Color.rgb(248,245,235)):Color.rgb(246,244,236),fg="night".equals(theme)&&active?Color.rgb(190,203,181):Color.rgb(81,88,75);root.setBackgroundColor(bg);strip.setBackgroundColor(bg);clock.setTextColor(fg);battery.setTextColor(fg);host.getWindow().setStatusBarColor(bg);host.getWindow().setNavigationBarColor(bg);
 if(Build.VERSION.SDK_INT>=30){WindowInsetsController controller=host.getWindow().getInsetsController();if(controller!=null){controller.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);controller.setSystemBarsAppearance("night".equals(theme)&&active?0:WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);if(hidden)controller.hide(WindowInsets.Type.statusBars());else controller.show(WindowInsets.Type.statusBars());}}
 else{int flags=View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN;if(!"night".equals(theme)||!active)flags|=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;if(hidden)flags|=View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY;host.getWindow().getDecorView().setSystemUiVisibility(flags);}if(!hidden)strip.setVisibility(View.GONE);root.requestApplyInsets();update();}
 private void update(){clock.setText(android.text.format.DateFormat.getTimeFormat(host).format(new Date()));Intent i=host.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int percent=i==null?-1:Math.round(100f*i.getIntExtra(BatteryManager.EXTRA_LEVEL,0)/Math.max(1,i.getIntExtra(BatteryManager.EXTRA_SCALE,100)));battery.setText(percent<0?"—":percent+"%");}
 boolean hidden(){return hidden;}
 void destroy(){handler.removeCallbacksAndMessages(null);if(registered){host.unregisterReceiver(receiver);registered=false;}}
}
